with with_windows as (select id, store_id, last_restock, sum(quantity) over (partition by product_id) as product_id_sum_quantity, lag(quantity, 1) over (partition by product_id, store_id order by last_restock, id) as prev_quantity, max(quantity) over (partition by store_id, product_id) as store_id_max_quantity from inventory) select date_trunc('week', last_restock) as week_start, round(avg(product_id_sum_quantity), 2) as avg_product_id_sum_quantity, count(distinct id) as distinct_ids, count(*) as cnt, round(avg(store_id_max_quantity), 2) as avg_store_id_max_quantity, percentile_approx(store_id_max_quantity, array(0.25, 0.5, 0.75)) as store_id_max_quantity_quartiles, count(distinct id) as distinct_ids_2 from with_windows group by date_trunc('week', last_restock) having round(avg(product_id_sum_quantity), 2) > 0;
